def next_greater_elements(nums):
    n = len(nums)
    ans, stack = [-1] * n, []
    for i in range(2 * n - 1, -1, -1):
        idx = i % n
        while stack and nums[stack[-1]] <= nums[idx]:
            stack.pop()
        if stack:
            ans[idx] = nums[stack[-1]]
        stack.append(idx)
    return ans

